// Outside agents act through the owner's account, so GitHub refuses their
// formal review on a PR that account opened. They end a summary with one
// verdict line instead. Same rule as factory_outside_verdict.py.
const VERDICT_LINE = /^Verdict: (changes-requested|approve)[ \t]*$/;
const MODEL_LINE = /^Model:[ \t]*\S/;
const FENCE = /^[ \t]*(```|~~~)/;
const RULE = /^[ \t]*-{3,}[ \t]*$/;
const TOOL_FOOTER = /^_Generated by .+_[ \t]*$/;
const SHA = /\b[0-9a-f]{7,40}\b/gi;
const COMMENT_WINDOW = 50;

function nonEmptyLines(body) {
  let fenced = false;
  const lines = [];
  for (const line of String(body || '').split(/\r?\n/)) {
    if (FENCE.test(line)) {
      fenced = !fenced;
      lines.push({ line, fenced: true });
    } else if (line.trim()) {
      lines.push({ line, fenced });
    }
  }
  // Connector apps append "---" and "_Generated by ..._" after the agent's text.
  const n = lines.length;
  if (n >= 2 && !lines[n - 1].fenced && !lines[n - 2].fenced
      && TOOL_FOOTER.test(lines[n - 1].line) && RULE.test(lines[n - 2].line)) {
    lines.splice(n - 2, 2);
  }
  return lines;
}

function verdictOf(body) {
  const lines = nonEmptyLines(body);
  const last = lines[lines.length - 1];
  if (!last || last.fenced) return null;
  const match = last.line.match(VERDICT_LINE);
  if (!match) return null;
  return lines.some(({ line, fenced }) => !fenced && MODEL_LINE.test(line)) ? match[1] : null;
}

function namesHead(body, head) {
  const wanted = String(head || '').toLowerCase();
  return Boolean(wanted) && (String(body || '').match(SHA) || [])
    .some(token => wanted.startsWith(token.toLowerCase()));
}

function ownerAuthored(item, owner) {
  const login = String(item?.user?.login || '');
  if (!login || item?.user?.type === 'Bot' || login.endsWith('[bot]')) return false;
  return login.toLowerCase() === String(owner || '').toLowerCase()
    || item?.author_association === 'OWNER';
}

// Latest owner verdict for this exact head. A review binds to its commit; a
// summary comment binds to the head SHA (7+ characters) it names.
function verdictAt({ reviews = [], comments = [], head, owner, markerPrefix }) {
  const marker = `${markerPrefix}-factory-`;
  const rows = [
    ...reviews.filter(review => review?.commit_id === head)
      .map(review => ({ item: review, at: review.submitted_at, source: 'review' })),
    ...comments.filter(comment => namesHead(comment?.body, head))
      .map(comment => ({ item: comment, at: comment.created_at, source: 'comment' })),
  ];
  let latest = null;
  for (const row of rows) {
    const body = String(row.item.body || '');
    if (!ownerAuthored(row.item, owner) || body.includes(marker)) continue;
    const verdict = verdictOf(body);
    if (verdict && (!latest || String(row.at || '') >= String(latest.at || ''))) {
      latest = { ...row, verdict, url: row.item.html_url || '', login: row.item.user.login };
    }
  }
  return latest;
}

async function liveReviews(github, context, number, deps) {
  const endpoint = `repos/${context.repo.owner}/${context.repo.repo}/pulls/${number}/reviews`;
  const response = await deps.manualPaginationWithLogging(github, context, {
    endpoint, method: 'GET', event: context.eventName,
  }, async (page, perPage, pageSpec) => deps.withRetryLogged(github, context, pageSpec, async () => {
    const result = await github.rest.pulls.listReviews({
      ...context.repo, pull_number: number, per_page: perPage, page,
    });
    return { data: result.data, headers: result.headers, status: result.status };
  }));
  return response.data;
}

async function recentComments(github, context, number, deps) {
  const response = await deps.withRetryLogged(github, context, {
    endpoint: 'graphql', kind: 'graphql', event: context.eventName,
  }, async () => {
    const result = await github.graphql(
      `query($owner:String!,$name:String!,$number:Int!){repository(owner:$owner,name:$name){pullRequest(number:$number){comments(last:${COMMENT_WINDOW}){nodes{body url createdAt authorAssociation author{__typename login}}}}}}`,
      { owner: context.repo.owner, name: context.repo.repo, number },
    );
    return { data: result, headers: {}, status: 200 };
  });
  return (response?.data?.repository?.pullRequest?.comments?.nodes || []).map(node => ({
    body: node.body,
    html_url: node.url,
    created_at: node.createdAt,
    author_association: node.authorAssociation,
    user: { login: node.author?.login || '', type: node.author?.__typename === 'Bot' ? 'Bot' : 'User' },
  }));
}

// Recomputed from live state on every owner review, thread reply and verdict
// event, so a replaced pending run in the per-PR group cannot lose a verdict.
// Bot events skip it to keep their API cost unchanged.
async function route(github, context, number, deps) {
  const event = context.payload?.review || context.payload?.comment;
  if (!ownerAuthored(event, context.repo.owner)) return { routed: false, reason: 'not-owner-event' };
  const current = await deps.currentLabels(github, context, number);
  if (!current.has('factory')) return { routed: false, reason: 'not-factory' };
  if (current.has('factory:building')) return { routed: false, reason: 'building' };
  const live = await deps.livePullRequest(github, context, number);
  if (!live || (live.state && live.state !== 'open')) return { routed: false, reason: 'not-open' };
  const head = live.head?.sha;
  const found = verdictAt({
    reviews: await liveReviews(github, context, number, deps),
    comments: await recentComments(github, context, number, deps),
    head,
    owner: context.repo.owner,
    markerPrefix: deps.markerPrefix,
  });
  if (!found) return { routed: false, reason: 'no-verdict' };
  if (found.verdict === 'approve') {
    console.log(`Outside verdict on PR #${number} head ${head}: approve by ${found.login} (${found.url}). Advisory only; a factory reviewer must still approve.`);
    return { routed: false, reason: 'advisory-approve', verdict: 'approve', url: found.url };
  }
  if (current.has('factory:changes-requested')) return { routed: false, reason: 'already-routed' };
  await deps.reconcileLabels(github, context, number, {
    owner: [...current].find(deps.isOwnerLabel) || await deps.ownerFromLinkedIssue(github, context, { ...live, number }),
    stage: 'factory:changes-requested',
    approved: false,
  });
  console.log(`Outside verdict on PR #${number} head ${head}: changes requested by ${found.login} (${found.url}).`);
  return { routed: true, verdict: 'changes-requested', url: found.url };
}

module.exports = { verdictOf, namesHead, ownerAuthored, verdictAt, route };
